ALTER TABLE profiles ADD COLUMN IF NOT EXISTS phone VARCHAR(32), ADD COLUMN IF NOT EXISTS must_change_password BOOLEAN DEFAULT FALSE, ADD COLUMN IF NOT EXISTS is_active BOOLEAN DEFAULT TRUE;
ALTER TABLE vehicles ADD COLUMN IF NOT EXISTS supported_waste_streams JSONB DEFAULT '["Mixed Recyclable"]'::jsonb, ADD COLUMN IF NOT EXISTS service_area TEXT, ADD COLUMN IF NOT EXISTS depot TEXT, ADD COLUMN IF NOT EXISTS operating_hours JSONB DEFAULT '{}'::jsonb, ADD COLUMN IF NOT EXISTS is_operational BOOLEAN DEFAULT TRUE, ADD COLUMN IF NOT EXISTS duty_status VARCHAR(16) DEFAULT 'off_duty', ADD COLUMN IF NOT EXISTS location_updated_at TIMESTAMPTZ;
ALTER TABLE bins ADD COLUMN IF NOT EXISTS qr_code VARCHAR(128), ADD COLUMN IF NOT EXISTS service_area TEXT, ADD COLUMN IF NOT EXISTS access_restrictions TEXT, ADD COLUMN IF NOT EXISTS access_hours JSONB DEFAULT '{}'::jsonb, ADD COLUMN IF NOT EXISTS reading_source VARCHAR(24) DEFAULT 'manual', ADD COLUMN IF NOT EXISTS sensor_status VARCHAR(24) DEFAULT 'unknown', ADD COLUMN IF NOT EXISTS reading_recorded_at TIMESTAMPTZ;
ALTER TABLE route_plans ADD COLUMN IF NOT EXISTS dispatch_mode VARCHAR(24) DEFAULT 'review', ADD COLUMN IF NOT EXISTS assignment_version INTEGER DEFAULT 1, ADD COLUMN IF NOT EXISTS accepted_at TIMESTAMPTZ, ADD COLUMN IF NOT EXISTS started_at TIMESTAMPTZ, ADD COLUMN IF NOT EXISTS handover_at TIMESTAMPTZ, ADD COLUMN IF NOT EXISTS actual_distance_km DOUBLE PRECISION, ADD COLUMN IF NOT EXISTS actual_started_at TIMESTAMPTZ;
ALTER TABLE route_stops ADD COLUMN IF NOT EXISTS estimated_quantity_kg DOUBLE PRECISION DEFAULT 0, ADD COLUMN IF NOT EXISTS service_time_minutes INTEGER DEFAULT 5;
ALTER TABLE alerts ADD COLUMN IF NOT EXISTS collection_request_id VARCHAR(96), ADD COLUMN IF NOT EXISTS acknowledged_at TIMESTAMPTZ;

CREATE TABLE IF NOT EXISTS bin_readings (id VARCHAR(96) PRIMARY KEY, bin_id VARCHAR(64) NOT NULL REFERENCES bins(id) ON DELETE CASCADE, fill_percentage DOUBLE PRECISION NOT NULL CHECK (fill_percentage BETWEEN 0 AND 100), measured_weight_kg DOUBLE PRECISION, estimated_weight_kg DOUBLE PRECISION, reading_source VARCHAR(24) NOT NULL CHECK (reading_source IN ('sensor','manual','verified_complaint')), sensor_status VARCHAR(24) DEFAULT 'healthy', recorded_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, recorded_at TIMESTAMPTZ DEFAULT NOW(), received_at TIMESTAMPTZ DEFAULT NOW(), idempotency_key VARCHAR(128) UNIQUE);
CREATE TABLE IF NOT EXISTS collection_requests (id VARCHAR(96) PRIMARY KEY, bin_id VARCHAR(64) NOT NULL REFERENCES bins(id) ON DELETE CASCADE, alert_id VARCHAR(64) REFERENCES alerts(id) ON DELETE SET NULL, urgency VARCHAR(16) NOT NULL DEFAULT 'normal', reason VARCHAR(32) NOT NULL, required_quantity_kg DOUBLE PRECISION DEFAULT 0, waste_stream VARCHAR(64), status VARCHAR(24) NOT NULL DEFAULT 'unassigned', assigned_vehicle_id VARCHAR(64) REFERENCES vehicles(id) ON DELETE SET NULL, assigned_route_id VARCHAR(64) REFERENCES route_plans(id) ON DELETE SET NULL, reservation_kg DOUBLE PRECISION DEFAULT 0, unassigned_reason TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW(), resolved_at TIMESTAMPTZ);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_request_per_bin ON collection_requests(bin_id) WHERE status IN ('unassigned','assigned','accepted','in_progress','partially_completed');
CREATE TABLE IF NOT EXISTS driver_shifts (id VARCHAR(96) PRIMARY KEY, driver_id VARCHAR(64) NOT NULL, user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL, vehicle_id VARCHAR(64) NOT NULL REFERENCES vehicles(id) ON DELETE RESTRICT, status VARCHAR(24) NOT NULL DEFAULT 'off_duty', started_at TIMESTAMPTZ, ended_at TIMESTAMPTZ, start_load_kg DOUBLE PRECISION DEFAULT 0, end_load_kg DOUBLE PRECISION, last_location_lat DOUBLE PRECISION, last_location_lng DOUBLE PRECISION, last_location_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE UNIQUE INDEX IF NOT EXISTS one_open_shift_per_driver ON driver_shifts(driver_id) WHERE status IN ('on_duty','paused');
CREATE TABLE IF NOT EXISTS vehicle_locations (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, vehicle_id VARCHAR(64) NOT NULL REFERENCES vehicles(id) ON DELETE CASCADE, driver_id VARCHAR(64), latitude DOUBLE PRECISION NOT NULL, longitude DOUBLE PRECISION NOT NULL, accuracy_m DOUBLE PRECISION, recorded_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS route_revisions (id VARCHAR(96) PRIMARY KEY, route_plan_id VARCHAR(64) NOT NULL REFERENCES route_plans(id) ON DELETE CASCADE, version INTEGER NOT NULL, reason TEXT NOT NULL, requires_acknowledgement BOOLEAN DEFAULT TRUE, acknowledged_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS operational_metrics (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, metric_date DATE NOT NULL, vehicle_id VARCHAR(64) REFERENCES vehicles(id) ON DELETE SET NULL, driver_id VARCHAR(64), collected_quantity_kg DOUBLE PRECISION DEFAULT 0, unloaded_quantity_kg DOUBLE PRECISION DEFAULT 0, rejected_quantity_kg DOUBLE PRECISION DEFAULT 0, completed_stops INTEGER DEFAULT 0, partial_stops INTEGER DEFAULT 0, blocked_stops INTEGER DEFAULT 0, missed_stops INTEGER DEFAULT 0, travel_distance_km DOUBLE PRECISION DEFAULT 0, overflow_incidents INTEGER DEFAULT 0, response_minutes DOUBLE PRECISION DEFAULT 0, verified_recovery_kg DOUBLE PRECISION DEFAULT 0, created_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(metric_date, vehicle_id, driver_id));

ALTER TABLE bin_readings ENABLE ROW LEVEL SECURITY;
ALTER TABLE collection_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE driver_shifts ENABLE ROW LEVEL SECURITY;
ALTER TABLE vehicle_locations ENABLE ROW LEVEL SECURITY;
ALTER TABLE route_revisions ENABLE ROW LEVEL SECURITY;
ALTER TABLE operational_metrics ENABLE ROW LEVEL SECURITY;

CREATE POLICY "supervisors manage bin readings" ON bin_readings FOR ALL TO authenticated USING (public.is_supervisor()) WITH CHECK (public.is_supervisor());
CREATE POLICY "supervisors manage collection requests" ON collection_requests FOR ALL TO authenticated USING (public.is_supervisor()) WITH CHECK (public.is_supervisor());
CREATE POLICY "drivers read assigned requests" ON collection_requests FOR SELECT TO authenticated USING (assigned_vehicle_id = (SELECT vehicle_id FROM profiles WHERE id = auth.uid()));
CREATE POLICY "drivers manage own shifts" ON driver_shifts FOR ALL TO authenticated USING (driver_id = public.current_driver_id()) WITH CHECK (driver_id = public.current_driver_id());
CREATE POLICY "supervisors read shifts" ON driver_shifts FOR SELECT TO authenticated USING (public.is_supervisor());
CREATE POLICY "drivers write own locations" ON vehicle_locations FOR INSERT TO authenticated WITH CHECK (driver_id = public.current_driver_id());
CREATE POLICY "supervisors read locations" ON vehicle_locations FOR SELECT TO authenticated USING (public.is_supervisor());
CREATE POLICY "drivers read assigned revisions" ON route_revisions FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM route_plans r WHERE r.id = route_plan_id AND r.driver_id = public.current_driver_id()));
CREATE POLICY "supervisors manage revisions" ON route_revisions FOR ALL TO authenticated USING (public.is_supervisor()) WITH CHECK (public.is_supervisor());
CREATE POLICY "supervisors read metrics" ON operational_metrics FOR SELECT TO authenticated USING (public.is_supervisor());